package org.l2jmobius.gameserver.managers;
import java.lang.classfile.*;import java.lang.classfile.instruction.*;import java.lang.constant.*;import java.lang.invoke.MethodHandles;import java.lang.reflect.*;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;
import org.l2jmobius.gameserver.entity.*;import org.l2jmobius.gameserver.entity.actor.Player;import org.l2jmobius.gameserver.entity.groups.Party;
import static java.lang.constant.ConstantDescs.*;

/** Настоящий checkConditions не меняется; контролируются только его зависимости сообщений и откатов. */
public class CavernConditionsCheck {
 static int checks,messages,queries;static Object reuseManager;static final Map<Player,Integer> LEVELS=new IdentityHashMap<>();static final Map<Integer,Long> REUSE=new HashMap<>();static Class<?> cavernType;static Object cavern;static Method conditions;
 static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 public static int level(Player p){return LEVELS.getOrDefault(p,85);}public static Object instanceManager(){return reuseManager;}public static long reuse(int id,int template){queries++;return REUSE.getOrDefault(id,0L);}public static void message(){messages++;}
 static final ClassFile CANON=ClassFile.of(ClassFile.ConstantPoolSharingOption.NEW_POOL,ClassFile.DebugElementsOption.DROP_DEBUG,ClassFile.LineNumbersOption.DROP_LINE_NUMBERS,ClassFile.StackMapsOption.DROP_STACK_MAPS);
 static String key(MethodModel m){return m.methodName().stringValue()+m.methodType().stringValue();}static String fp(MethodModel m)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(CANON.build(m.parent().orElseThrow().thisClass().asSymbol(),b->b.transformMethod(m,MethodTransform.transformingCode((cb,e)->{if(e instanceof Instruction||e instanceof LabelTarget||e instanceof ExceptionCatch)cb.with(e);})))));}
 static byte[] boundary(byte[] input,boolean script)throws Exception{
  var cf=ClassFile.of();var before=cf.parse(input);ClassDesc host=ClassDesc.of(CavernConditionsCheck.class.getName());
  byte[] result=cf.transformClass(before,(b,e)->{
   if(e instanceof MethodModel m){String name=m.methodName().stringValue();if(script&&name.equals("broadcastSystemMessage")){b.withMethodBody(name,m.methodTypeSymbol(),m.flags().flagsMask(),c->c.invokestatic(host,"message",MethodTypeDesc.of(CD_void)).return_());return;}
    if(!script&&name.equals("getInstance")&&m.methodType().equalsString("()Lorg/l2jmobius/gameserver/managers/InstanceManager;")){b.withMethodBody(name,m.methodTypeSymbol(),m.flags().flagsMask(),c->c.invokestatic(host,"instanceManager",MethodTypeDesc.of(CD_Object)).checkcast(before.thisClass().asSymbol()).areturn());return;}
    if(!script&&name.equals("getInstanceTime")&&m.methodType().equalsString("(II)J")){b.withMethodBody(name,m.methodTypeSymbol(),m.flags().flagsMask(),c->c.iload(1).iload(2).invokestatic(host,"reuse",MethodTypeDesc.of(CD_long,CD_int,CD_int)).lreturn());return;}
   }b.with(e);
  });
  if(script){var original=before.methods().stream().filter(m->m.methodName().equalsString("checkConditions")).findFirst().orElseThrow();var after=CANON.parse(result).methods().stream().filter(m->key(m).equals(key(original))).findFirst().orElseThrow();check(fp(original).equals(fp(after)),"actual checkConditions instructions unmodified");}
  return result;
 }
 static int constant(String name)throws Exception{Field f=cavernType.getDeclaredField(name);f.setAccessible(true);return f.getInt(null);}
 static Player player(boolean gm,boolean playing)throws Exception{Player p=PlayingGmStateCheck.player(gm);p.getVariables().set(PlayingGmPolicy.MODE_VARIABLE,playing);return p;}
 static List<Player> group(Player leader,int size)throws Exception{List<Player> people=new ArrayList<>();people.add(leader);for(int i=1;i<size;i++)people.add(player(false,false));Party party=(Party)PlayingGmStateCheck.u.allocateInstance(Party.class);PlayingGmStateCheck.put(party,Party.class,"_members",people);for(Player p:people)p.setParty(party);return people;}
 static boolean call(Player p,int template)throws Exception{try{return(boolean)conditions.invoke(cavern,p,template);}catch(InvocationTargetException e){throw new RuntimeException(e.getCause());}}
 static void route(int template,String minName)throws Exception{
  int min=constant(minName),level=constant("MIN_LV_60");check(min>=2,"Native threshold read, not modified");Player full=player(true,false),playing=player(true,true),normal=player(false,false);check(call(full,template),"full GM retains legacy no-party bypass");check(!call(playing,template)&&!call(normal,template),"playing GM equals ordinary no-party rejection");
  group(playing,min-1);check(!call(playing,template),"playing GM must satisfy actual group-size threshold");List<Player> members=group(playing,min);queries=0;check(call(playing,template)&&queries==min,"playing GM valid group checks every member reuse");check(playing.isGM()&&playing.getAccessLevel().getLevel()==70,"instance validation never changes raw GM/ACL");
  check(!call(members.get(1),template),"only actual Native group leader can enter");LEVELS.put(members.get(1),level-1);check(!call(playing,template),"low-level member rejected");LEVELS.remove(members.get(1));PlayingGmStateCheck.put(members.get(1),WorldObject.class,"_location",new Location(1001,0,0));check(!call(playing,template),"distant member rejected");PlayingGmStateCheck.put(members.get(1),WorldObject.class,"_location",new Location(0,0,0));REUSE.put(members.get(1).getObjectId(),Long.MAX_VALUE);check(!call(playing,template),"member on reuse blocks playing GM leader");REUSE.clear();check(call(playing,template),"same group accepted after controlled reuse expires");
  System.out.println("CAVERN_REAL_CONDITIONS template="+template+" unchanged_min="+min+" fullGM_bypass=true playing_and_ordinary_requirements=true");
 }
 public static void main(String[] args)throws Exception{try{
  Field f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);PlayingGmStateCheck.u=(sun.misc.Unsafe)f.get(null);ClassDesc pc=ClassDesc.of(Player.class.getName()),host=ClassDesc.of(CavernConditionsCheck.class.getName());PlayingGmStateCheck.actorType=MethodHandles.lookup().defineClass(ClassFile.of().build(ClassDesc.of("org.l2jmobius.gameserver.managers.CavernFixturePlayer"),b->{b.withFlags(0x31);b.withSuperclass(pc);b.withMethodBody("getLevel",MethodTypeDesc.of(CD_int),1,c->c.aload(0).invokestatic(host,"level",MethodTypeDesc.of(CD_int,pc)).ireturn());}));
  Path compiled=Path.of(args[0]);String script="instances.CavernOfThePirateCaptain.CavernOfThePirateCaptain",manager=InstanceManager.class.getName();
  ClassLoader loader=new ClassLoader(CavernConditionsCheck.class.getClassLoader()){@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(!name.startsWith(script)&&!name.equals(manager))return super.loadClass(name,resolve);synchronized(getClassLoadingLock(name)){Class<?> c=findLoadedClass(name);if(c==null)try{String rel=name.replace('.','/')+".class";byte[] raw=name.equals(manager)?getParent().getResourceAsStream(rel).readAllBytes():Files.readAllBytes(compiled.resolve(rel));byte[] bytes=name.equals(manager)||name.equals(script)?boundary(raw,name.equals(script)):raw;c=defineClass(name,bytes,0,bytes.length);}catch(Throwable error){throw new ClassNotFoundException(name,error);}if(resolve)resolveClass(c);return c;}}};
  Class<?> m=loader.loadClass(manager);reuseManager=PlayingGmStateCheck.u.allocateInstance(m);cavernType=loader.loadClass(script);cavern=PlayingGmStateCheck.u.allocateInstance(cavernType);conditions=cavernType.getDeclaredMethod("checkConditions",Player.class,int.class);conditions.setAccessible(true);check(PlayingGmPolicy.isEnabled(),"real PlayingGm config enabled");route(constant("TEMPLATE_ID_60"),"PLAYERS_60_MIN");route(constant("TEMPLATE_ID_60_NIGHT"),"PLAYERS_60_NIGHT_MIN");check(messages>0,"rejections reached recorded packet terminal");System.out.println("CAVERN_PLAYING_GM_CHECK_OK checks="+checks+" real compiled checkConditions untouched; Native party/leader/distance and raw GM; level/reuse/group-input/packet terminals controlled; no existing-instance/reentry/World/SQL/client claim");System.exit(0);
 }catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
